-- Private 5-model, 15-section factory evidence batch. No auto-publication.
DO $$
DECLARE n integer; inserted integer; initial_public integer; final_public integer;
BEGIN
 SELECT count(*) INTO initial_public FROM public.motorcycle_universal_published_sections_v1;
 WITH wanted(id,make,model) AS (VALUES (209,'KTM','890 SMT'),
(884,'KTM','1390 Super Adventure'),
(251,'Triumph','STREET TRIPLE 765 RS'),
(532,'KTM','RC 8C'),
(669,'Triumph','Speed Triple 1200 RR'))
 SELECT count(*) INTO n FROM wanted w JOIN public.motorcycle_catalog_models m ON m.id=w.id AND m.manufacturer=w.make AND m.model=w.model
 WHERE NOT EXISTS(SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s WHERE s.entity_type='model' AND s.model_id=w.id)
 AND NOT EXISTS(SELECT 1 FROM public.motorcycle_catalog_model_aliases a WHERE a.alias_model_id=w.id AND a.review_status<>'approved')
 AND EXISTS(SELECT 1 FROM public.motorcycle_catalog_manufacturers r WHERE r.display_name=w.make);
 IF n<>5 THEN RAISE EXCEPTION 'Intake halted: 5 exact model identities not eligible (% found)',n; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,x.model_id,x.slot,x.title,x.content,'draft','original_factory_press:'||x.url,NULL
 FROM (VALUES (209,1,'Model introduction','{"summary":"The KTM 890 SMT is a road-focused sport-tourer mixing the brand''s Supermoto character with longer-distance riding ability.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-king-of-the-comebacks-hail-the-new-ktm-890-smt?id=177025&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-king-of-the-comebacks-hail-the-new-ktm-890-smt?id=177025&l=uk&menueid=5904'),
(209,7,'Documented launch','{"summary":"KTM''s April 2023 announcement reintroduced the SMT line with the 890 SMT and indicated UK dealership arrivals from May 2023.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-king-of-the-comebacks-hail-the-new-ktm-890-smt?id=177025&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-king-of-the-comebacks-hail-the-new-ktm-890-smt?id=177025&l=uk&menueid=5904'),
(209,12,'2023 equipment context','{"summary":"The UK announcement describes an LC8c platform, 17-inch wheels and five-inch TFT display; Quickshifter+ and cruise control were offered as optional equipment.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-king-of-the-comebacks-hail-the-new-ktm-890-smt?id=177025&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-king-of-the-comebacks-hail-the-new-ktm-890-smt?id=177025&l=uk&menueid=5904'),
(884,1,'Model introduction','{"summary":"KTM''s 1390 Super Adventure is a large-capacity V-twin adventure motorcycle family with distinct S, R and S EVO variants.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-ktm-release-production-update-on-new-generation-street-and-adventure-model-line-up?id=222356&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-ktm-release-production-update-on-new-generation-street-and-adventure-model-line-up?id=222356&l=international&menueid=3050'),
(884,7,'Official production status','{"summary":"KTM''s 2025 production update scheduled the start of production of the 1390 Super Adventure S, S EVO and R for October 2025. Production timing is not proof of identical worldwide retail delivery dates.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-ktm-release-production-update-on-new-generation-street-and-adventure-model-line-up?id=222356&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-ktm-release-production-update-on-new-generation-street-and-adventure-model-line-up?id=222356&l=international&menueid=3050'),
(884,12,'Variant-specific caution','{"summary":"The 1390 Super Adventure family includes R, S and S EVO versions. Semi-active suspension or automated-shift features mentioned for one variant must not be assigned to the entire family.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-ktm-release-production-update-on-new-generation-street-and-adventure-model-line-up?id=222356&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-ktm-release-production-update-on-new-generation-street-and-adventure-model-line-up?id=222356&l=international&menueid=3050'),
(251,1,'Model introduction','{"summary":"The Street Triple 765 RS is a higher-performance variant of Triumph''s three-cylinder naked road motorcycle.","source_name":"Triumph original factory report","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/street-triple-765-2022-11-03","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/street-triple-765-2022-11-03'),
(251,7,'2023 revision','{"summary":"Triumph unveiled a significantly updated Street Triple 765 RS for model year 2023 in November 2022, alongside separate Street Triple R and Moto2 editions.","source_name":"Triumph original factory report","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/street-triple-765-2022-11-03","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/street-triple-765-2022-11-03'),
(251,12,'2023 RS-specific engineering','{"summary":"Triumph''s announcement quotes 130 PS at 12,000 rpm and 80 Nm at 9,500 rpm for the 2023 RS generation, with Brembo Stylema brakes. These figures are not universal across all 765 trims.","source_name":"Triumph original factory report","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/street-triple-765-2022-11-03","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/street-triple-765-2022-11-03'),
(532,1,'Model introduction','{"summary":"The KTM RC 8C is a circuit-oriented, limited-production motorcycle developed with Krämer rather than a conventional road-going RC model.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-the-2024-ktm-rc-8c-is-ready-to-bring-limited-ktm-sportmotorcycle?id=195864&imageid=759091&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-the-2024-ktm-rc-8c-is-ready-to-bring-limited-ktm-sportmotorcycle?id=195864&imageid=759091&l=international&menueid=3050'),
(532,7,'2024 limited production','{"summary":"KTM announced a 100-unit hand-built 2024 RC 8C edition in March 2024, with an online ordering process.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-the-2024-ktm-rc-8c-is-ready-to-bring-limited-ktm-sportmotorcycle?id=195864&imageid=759091&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-the-2024-ktm-rc-8c-is-ready-to-bring-limited-ktm-sportmotorcycle?id=195864&imageid=759091&l=international&menueid=3050'),
(532,12,'2024 track specification context','{"summary":"KTM''s 2024 announcement describes an 889 cc twin-cylinder engine, dedicated circuit chassis and racing wheels and tyres; previous RC 8C editions differ.","source_name":"KTM original factory report","source_url":"https://press.ktm.com/news-the-2024-ktm-rc-8c-is-ready-to-bring-limited-ktm-sportmotorcycle?id=195864&imageid=759091&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://press.ktm.com/news-the-2024-ktm-rc-8c-is-ready-to-bring-limited-ktm-sportmotorcycle?id=195864&imageid=759091&l=international&menueid=3050'),
(669,1,'Model introduction','{"summary":"The Speed Triple 1200 RR is Triumph''s more sports-focused, half-faired version of the Speed Triple 1200 family.","source_name":"Triumph original factory report","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-speed-triple-rr-22-04-12","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-speed-triple-rr-22-04-12'),
(669,7,'Original-market timing','{"summary":"Triumph''s official RR interview indicated dealership availability from early spring 2022, depending on market and location.","source_name":"Triumph original factory report","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-speed-triple-rr-22-04-12","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-speed-triple-rr-22-04-12'),
(669,12,'RR variant specification','{"summary":"Triumph describes lower clip-on bars, rear-set footpegs and Öhlins Smart EC 2.0 electronically adjustable suspension for the RR, distinguishing it from the RS cockpit and chassis setup.","source_name":"Triumph original factory report","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-speed-triple-rr-22-04-12","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Source reviewed for intake, but factual editorial signoff, rights and exact year/market checks outstanding."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/reviews/q-and-a-speed-triple-rr-22-04-12')) x(model_id,slot,title,content,url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>15 THEN RAISE EXCEPTION 'Expected 15 draft slots; inserted %',inserted; END IF;
 SELECT count(*) INTO final_public FROM public.motorcycle_universal_published_sections_v1;
 IF final_public<>initial_public THEN RAISE EXCEPTION 'Published universal research changed'; END IF;
END $$;